/* Dune BYOP runtime.wasm loader -- generated by tools/wasm_runtime/build_runtime.py.
 *
 * Small ES module for browsers and Node: owns the single WebAssembly.Memory,
 * instantiates the prebuilt runtime.wasm, reads the versioned ABI descriptor and
 * exposes the ROM buffer / game-module table helpers.  No emscripten JS glue is
 * used: runtime.wasm is a STANDALONE_WASM module with imported memory, so every
 * ``env``/WASI import is supplied here (overridable by the host).
 *
 * Browser usage:
 *   import { loadRuntime, initRuntime } from './runtime/wasm/loader.mjs';
 *   const rt = await loadRuntime({ url: new URL('./runtime/wasm/runtime.wasm', import.meta.url) });
 *   initRuntime(rt);                       // dune_rt_init(); fills rt.abi
 *   rt.exports.dune_rt_rom_buffer()        // copy player ROM into memory
 *
 * Node usage: pass wasmBytes (fs.readFile) or a WebAssembly.Module.
 */

export const ABI_FIELDS = ["MAGIC", "VERSION", "SIZE", "ABI_HASH_0", "ABI_HASH_1", "ABI_HASH_2", "ABI_HASH_3", "ABI_HASH_4", "ABI_HASH_5", "ABI_HASH_6", "ABI_HASH_7", "HELPER_ABI_VERSION", "SIZEOF_CPU", "OFF_D", "OFF_A", "OFF_PC", "OFF_USP", "OFF_SSP", "OFF_SR", "OFF_RAM", "OFF_IO_DATA", "OFF_IO_CONTROL", "OFF_TMSS", "OFF_IO_TX", "OFF_IO_SERIAL_CONTROL", "OFF_PAD_BUTTONS", "OFF_FAULT", "OFF_FAULT_ADDRESS", "OFF_REASON", "OFF_INSTRUCTION_CYCLES", "OFF_Z80_DIVIDER", "OFF_STEPS", "OFF_CYCLES", "OFF_MASTER_CYCLES", "OFF_INTERRUPTS", "OFF_HALTED", "OFF_ROM", "OFF_ROM_SIZE", "OFF_VDP", "OFF_VDP_REGISTERS", "OFF_VDP_VRAM", "OFF_VDP_CRAM", "OFF_VDP_VSRAM", "OFF_VDP_FRAME", "OFF_VDP_FRAME_WIDTH", "OFF_VDP_FRAME_HEIGHT", "SIZEOF_Z80CPU", "OFF_Z80_CPU", "OFF_Z80_R8", "OFF_Z80_ALTERNATE", "OFF_Z80_A", "OFF_Z80_F", "OFF_Z80_A_ALT", "OFF_Z80_F_ALT", "OFF_Z80_I", "OFF_Z80_R", "OFF_Z80_IFF1", "OFF_Z80_IFF2", "OFF_Z80_IM", "OFF_Z80_HALTED", "OFF_Z80_IRQ_LINE", "OFF_Z80_EI_DELAY", "OFF_Z80_PC", "OFF_Z80_SP", "OFF_Z80_IX", "OFF_Z80_IY", "OFF_Z80_WZ", "OFF_Z80_DEBT", "OFF_Z80_STEPS", "OFF_Z80_CYCLES", "OFF_Z80_INTERRUPTS", "OFF_Z80_BUS", "OFF_Z80_RAM", "OFF_Z80_BUS_REQUESTED", "OFF_Z80_BUS_RESET_RELEASED", "OFF_Z80_BUS_BANK", "SIZEOF_SAVESTATE", "SAVESTATE_RAM_OFFSET", "SAVESTATE_HOUSE_OFFSET", "SAVESTATE_MISSION_OFFSET", "SAVESTATE_YM_SIZE_FIELD_OFFSET", "SAVESTATE_TOTAL_SIZE_FIELD_OFFSET", "SAVESTATE_MAGIC", "SAVESTATE_VERSION", "SAVE_BUFFER_BYTES", "ROM_CAPACITY", "PAGE_SHIFT", "PAGE_SIZE", "PAGE_SLOTS", "ROM_PAGES", "RAM_PAGE_FIRST", "RAM_PAGE_COUNT", "GAME_MODE_NONE", "GAME_MODE_PAGES", "GAME_MODE_SINGLE", "F_C", "F_V", "F_Z", "F_N", "F_X", "Z_C", "Z_N", "Z_PV", "Z_X", "Z_H", "Z_Y", "Z_Z", "Z_S", "SHIFT_KIND_ARITH", "SHIFT_KIND_LOGICAL", "SHIFT_KIND_ROX", "SHIFT_KIND_ROT", "SIZE_B", "SIZE_W", "SIZE_L", "UNTRANSLATED", "BAD_PC", "ODD_PC", "UNMAPPED", "RAM_VARIANT", "PRIVILEGE", "ADDRESS_ERROR", "UNMAPPED_READ", "UNMAPPED_WRITE", "ILLEGAL_INSTRUCTION", "DIVISION_BY_ZERO", "SERIAL_NOT_IMPLEMENTED", "VDP_ACCESS", "Z80_PERIPHERAL", "ADDR_CPU", "ADDR_RAM", "ADDR_Z80_RAM", "ADDR_ROM", "ADDR_SAVE_BUFFER", "ADDR_VDP_VRAM", "ADDR_VDP_CRAM", "ADDR_VDP_VSRAM", "ADDR_VDP_FRAME", "ADDR_GAME_TABLE", "ADDR_ABI"];

export const ABI = {
  "version": 1,
  "helperVersion": 1,
  "wordCount": 140,
  "layoutEnd": 129,
  "addressesStart": 129,
  "hash": {
    "words": 8,
    "firstWord": 3,
    "inputWordRanges": [
      [
        0,
        3
      ],
      [
        11,
        129
      ]
    ]
  },
  "addressFields": [
    "ADDR_CPU",
    "ADDR_RAM",
    "ADDR_Z80_RAM",
    "ADDR_ROM",
    "ADDR_SAVE_BUFFER",
    "ADDR_VDP_VRAM",
    "ADDR_VDP_CRAM",
    "ADDR_VDP_VSRAM",
    "ADDR_VDP_FRAME",
    "ADDR_GAME_TABLE",
    "ADDR_ABI"
  ],
  "failCodes": {
    "UNTRANSLATED": 1,
    "BAD_PC": 2,
    "ODD_PC": 3,
    "UNMAPPED": 4,
    "RAM_VARIANT": 5,
    "PRIVILEGE": 6,
    "ADDRESS_ERROR": 7,
    "UNMAPPED_READ": 8,
    "UNMAPPED_WRITE": 9,
    "ILLEGAL_INSTRUCTION": 10,
    "DIVISION_BY_ZERO": 11,
    "SERIAL_NOT_IMPLEMENTED": 12,
    "VDP_ACCESS": 13,
    "Z80_PERIPHERAL": 14
  },
  "dispatch": {
    "pageShift": 12,
    "pageSize": 4096,
    "pageSlots": 4096,
    "romPages": 256,
    "ramPageFirst": 4080,
    "ramPageCount": 16,
    "modeNone": 0,
    "modePages": 1,
    "modeSingle": 2
  },
  "rom": {
    "capacity": 1048576
  },
  "saveBuffer": {
    "bytes": 262144
  },
  "memory": {
    "initialPages": 1024,
    "maximumPages": 8192,
    "initialBytes": 67108864,
    "maximumBytes": 536870912,
    "stackBytes": 16777216
  }
};

export const ABI_INDEX = Object.freeze(
  Object.fromEntries(ABI_FIELDS.map((name, index) => [name, index])),
);

/* ---------------------------------------------------------------- memory -- */

export function createMemory({ initialPages = ABI.memory.initialPages, maximumPages = ABI.memory.maximumPages } = {}) {
  return new WebAssembly.Memory({ initial: initialPages, maximum: maximumPages });
}

/* ------------------------------------------------------- imports / mocks -- */

function wasiFdWrite(memory, fd, iovs, iovsLength, nwrittenPtr) {
  let total = 0;
  const view = new DataView(memory.buffer);
  for (let i = 0; i < iovsLength; i += 1) {
    const ptr = view.getUint32(iovs + i * 8, true);
    const length = view.getUint32(iovs + i * 8 + 4, true);
    if (fd === 2 && total + length <= 1 << 20) {
      const bytes = new Uint8Array(memory.buffer, ptr, length);
      if (typeof console !== 'undefined') console.error(new TextDecoder().decode(bytes).trimEnd());
    }
    total += length;
  }
  view.setUint32(nwrittenPtr, total, true);
  return 0;
}

function wasiStub(memory, name) {
  switch (name) {
    case 'fd_write':
      return (fd, iovs, iovsLength, nwritten) => wasiFdWrite(memory, fd, iovs, iovsLength, nwritten);
    case 'fd_read':
      return (fd, iovs, iovsLength, nread) => {
        new DataView(memory.buffer).setUint32(nread, 0, true);
        return 0;
      };
    case 'environ_sizes_get':
      return (countPtr, sizePtr) => {
        const view = new DataView(memory.buffer);
        view.setUint32(countPtr, 0, true);
        view.setUint32(sizePtr, 0, true);
        return 0;
      };
    case 'clock_time_get':
      return (clockId, precision, timePtr) => {
        const view = new DataView(memory.buffer);
        view.setBigUint64(timePtr, 0n, true);
        return 0;
      };
    default:
      return () => 0;
  }
}

/**
 * Build a WebAssembly import object for ``module``.
 *
 * Defaults: the shared memory for ``env.memory``, a zero WASI implementation and
 * a no-op function for every other import.  ``overrides`` is a nested
 * ``{ env: { name: fn }, wasi_snapshot_preview1: { ... } }`` map for the real
 * host (SDL/EM_JS/audio bridges) and for tests.
 *
 * ``virtualWindow`` ({ width, height }) turns on the "path A" virtual-window
 * mocks.  Only one of the SDL geometry dependencies is a real ``env`` import
 * (``emscripten_get_element_css_size``, which writes two doubles); the
 * ``SDL_*`` geometry calls are compiled into runtime.wasm and are answered by
 * the C ``--wrap`` shim instead (tools/wasm_runtime/src/dune_rt_virtual_window.inc,
 * enabled by ``dune_web_attach_virtual_window()``).  Defaults to no mock so
 * pure module tests keep the zero-stub surface.
 */
export function makeImportObject(module, { memory, overrides = {}, onStub = null, virtualWindow = null } = {}) {
  const importObject = {};
  // Read the size on every call: the virtual window changes with orientation and
  // must stay in sync with the C attach (a stale mock broke portrait hit-tests).
  const virtualCssSize = () => ({
    width: Math.max(1, Math.trunc(virtualWindow?.width ?? 320)),
    height: Math.max(1, Math.trunc(virtualWindow?.height ?? 224)),
  });
  for (const entry of WebAssembly.Module.imports(module)) {
    const group = (importObject[entry.module] ??= {});
    const override = overrides[entry.module]?.[entry.name];
    if (override !== undefined) {
      group[entry.name] = override;
      continue;
    }
    if (entry.kind === 'memory') {
      group[entry.name] = memory;
    } else if (entry.kind === 'function') {
      if (virtualWindow && entry.module === 'env' && entry.name === 'emscripten_get_element_css_size') {
        /* void emscripten_get_element_css_size(const char*, double *w, double *h);
           The pinned adapters treat the emscripten result 0 as success and fall
           back to the SDL window size for non-positive CSS sizes. */
        group[entry.name] = (_target, widthPtr, heightPtr) => {
          const size = virtualCssSize();
          const view = new DataView(memory.buffer);
          if (widthPtr) view.setFloat64(widthPtr, size.width, true);
          if (heightPtr) view.setFloat64(heightPtr, size.height, true);
          return 0;
        };
      } else {
        group[entry.name] = entry.module.startsWith('wasi_')
          ? wasiStub(memory, entry.name)
          : (() => 0);
      }
      if (onStub) onStub(entry, group[entry.name]);
    } else if (entry.kind === 'global') {
      group[entry.name] = new WebAssembly.Global({ value: 'i32', mutable: true }, 0);
    } else if (entry.kind === 'table') {
      group[entry.name] = new WebAssembly.Table({ initial: 0, element: 'anyfunc' });
    } else {
      throw new Error(`unsupported import kind ${entry.kind} for ${entry.module}.${entry.name}`);
    }
  }
  return importObject;
}

/* --------------------------------------------------------------- load -- */

async function readWasmSource({ url, wasmBytes, wasmModule }) {
  if (wasmModule instanceof WebAssembly.Module) return { module: wasmModule, bytes: null };
  let bytes = wasmBytes;
  if (!bytes) {
    if (!url) throw new Error('loadRuntime needs one of { url, wasmBytes, wasmModule }');
    if (typeof fetch === 'function') {
      const response = await fetch(url);
      if (!response.ok) throw new Error(`cannot fetch runtime.wasm: HTTP ${response.status}`);
      bytes = new Uint8Array(await response.arrayBuffer());
    } else {
      const { readFile } = await import('node:fs/promises');
      bytes = new Uint8Array(await readFile(url));
    }
  }
  return { module: await WebAssembly.compile(bytes), bytes };
}

/**
 * Compile + instantiate runtime.wasm, run C++/libc initialisers.
 * Returns ``{ module, instance, exports, memory, imports, bytes, abi: null }``.
 * Call :func:`initRuntime` (or ``exports.dune_rt_init()``) before reading ABI
 * addresses such as the ROM buffer.
 */
export async function loadRuntime({ url = null, wasmBytes = null, wasmModule = null, memory = null, importOverrides = {}, virtualWindow = null, skipInitialize = false } = {}) {
  const { module, bytes } = await readWasmSource({ url, wasmBytes, wasmModule });
  const sharedMemory = memory ?? createMemory();
  const imports = makeImportObject(module, { memory: sharedMemory, overrides: importOverrides, virtualWindow });
  const instance = await WebAssembly.instantiate(module, imports);
  if (!skipInitialize && typeof instance.exports._initialize === 'function') {
    instance.exports._initialize();
  }
  return { module, instance, exports: instance.exports, memory: sharedMemory, imports, bytes, abi: null };
}

/* ---------------------------------------------------------------- ABI -- */

export function readAbi(rt) {
  const pointer = rt.exports.dune_abi_descriptor();
  const words = new Uint32Array(rt.memory.buffer, pointer, ABI.wordCount).slice();
  const fields = {};
  for (let i = 0; i < ABI_FIELDS.length; i += 1) fields[ABI_FIELDS[i]] = words[i];
  const addresses = {};
  for (const name of ABI.addressFields) addresses[name] = fields[name];
  const abi = { pointer, words, fields, addresses };
  rt.abi = abi;
  return abi;
}

function wordsToBytes(words, from, to) {
  const out = new Uint8Array((to - from) * 4);
  const view = new DataView(out.buffer);
  for (let i = from; i < to; i += 1) view.setUint32((i - from) * 4, words[i], true);
  return out;
}

/** Recompute the SHA-256 ABI hash from the structural descriptor words. */
export async function computeAbiHash(abi) {
  if (!abi) throw new Error('computeAbiHash(abi): pass readAbi(runtime)');
  const parts = ABI.hash.inputWordRanges.map(([from, to]) => wordsToBytes(abi.words, from, to));
  const size = parts.reduce((sum, part) => sum + part.length, 0);
  const input = new Uint8Array(size);
  let offset = 0;
  for (const part of parts) {
    input.set(part, offset);
    offset += part.length;
  }
  const digest = new Uint8Array(
    await globalThis.crypto.subtle.digest('SHA-256', input.buffer),
  );
  return digest;
}

/** ``true`` when the descriptor's stored abi_hash matches its structural words. */
export async function verifyAbiHash(abi) {
  const digest = await computeAbiHash(abi);
  const start = ABI.hash.firstWord;
  for (let i = 0; i < ABI.hash.words; i += 1) {
    const stored = abi.words[start + i];
    const actual =
      (digest[i * 4] | (digest[i * 4 + 1] << 8) | (digest[i * 4 + 2] << 16) | (digest[i * 4 + 3] << 24)) >>> 0;
    if (stored !== actual) return false;
  }
  return true;
}

export async function abiHashHex(abi) {
  return Array.from(await computeAbiHash(abi), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

/** Call dune_rt_init() and read the ABI descriptor. */
export function initRuntime(rt) {
  rt.exports.dune_rt_init();
  return readAbi(rt);
}

/* -------------------------------------------------------- ROM / table -- */

/** Uint8Array view over the 1 MiB player-ROM buffer (valid until memory grows). */
export function romView(rt) {
  const pointer = rt.exports.dune_rt_rom_buffer();
  if (!pointer) throw new Error('dune_rt_init() has not allocated the ROM buffer');
  return new Uint8Array(rt.memory.buffer, pointer, ABI.rom.capacity);
}

/** Copy player ROM bytes into runtime memory (never into the wasm module). */
export function loadRom(rt, bytes) {
  if (bytes.length > ABI.rom.capacity) {
    throw new Error(`ROM is ${bytes.length} bytes, buffer capacity is ${ABI.rom.capacity}`);
  }
  const view = romView(rt);
  view.fill(0);
  view.set(bytes);
  return view.byteLength;
}

/** Read back ``length`` ROM bytes starting at ``offset``. */
export function readRom(rt, offset, length) {
  const view = romView(rt);
  return view.subarray(offset, offset + length);
}

/** Uint32Array view over the runtime's page table (funcref indices). */
export function gameTableView(rt) {
  const pointer = rt.exports.dune_rt_game_table();
  return new Uint32Array(rt.memory.buffer, pointer, ABI.dispatch.pageSlots);
}

/** Append WebAssembly functions to the runtime's indirect table; returns slots. */
export function appendFunctions(rt, functions) {
  const table = rt.exports.__indirect_function_table;
  if (!table) throw new Error('runtime.wasm does not export __indirect_function_table');
  const first = table.length;
  table.grow(functions.length);
  functions.forEach((fn, index) => table.set(first + index, fn));
  return Array.from({ length: functions.length }, (_, index) => first + index);
}

/**
 * Install a game table.  ``slots`` is an iterable of funcref indices:
 *  * 2 entries            -> single-dispatcher mode (translated_step, translated_z80_step),
 *  * 256 or 4096 entries  -> per-page handlers indexed by pc>>12.
 */
export function installGameTable(rt, slots, { count = null } = {}) {
  const list = Array.from(slots);
  const table = gameTableView(rt);
  const n = count ?? list.length;
  if (n === 2) {
    table[0] = list[0];
    table[1] = list[1];
  } else {
    if (n !== ABI.dispatch.romPages && n !== ABI.dispatch.pageSlots) {
      throw new Error(`game table must have 2, ${ABI.dispatch.romPages} or ${ABI.dispatch.pageSlots} entries`);
    }
    table.fill(0);
    table.set(list.slice(0, n));
  }
  const pointer = rt.exports.dune_rt_game_table();
  const result = rt.exports.dune_rt_set_game_table(pointer, n);
  if (result !== 0) throw new Error(`dune_rt_set_game_table failed (${result})`);
  return rt.exports.dune_rt_game_mode();
}

/** Decode a NUL-terminated UTF-8 C string from linear memory (fail reasons). */
export function cString(rt, pointer) {
  if (!pointer) return '';
  const bytes = new Uint8Array(rt.memory.buffer, pointer);
  let end = 0;
  while (end < bytes.length && bytes[end] !== 0) end += 1;
  return new TextDecoder().decode(bytes.subarray(0, end));
}

/** Mark the host window as attached (Phase-1 hook; run_main does this in production). */
export function setWindow(rt, enabled) {
  rt.exports.dune_rt_set_window(enabled ? 1 : 0);
}

/**
 * Attach the path-A virtual SDL window (see docs/WASM-TOUCH.md).
 *
 * Call after ``initRuntime()`` and after the game module is installed.  The
 * pinned camera/tap/hover adapters then see a valid 320x224 surface instead of
 * NULL ``SDL_Window``/``SDL_Renderer`` pointers.  Nothing is presented through
 * SDL; rendering stays on ``dune_web_frame_rgb()``.
 *
 * Returns the C function's result (1 on success); throws when the runtime predates
 * the export so a stale runtime.wasm fails loudly instead of silently returning 0.
 */
export function attachVirtualWindow(rt, width = 320, height = 224) {
  if (typeof rt.exports.dune_web_attach_virtual_window !== 'function') {
    throw new Error('runtime.wasm has no dune_web_attach_virtual_window (rebuild runtime/wasm)');
  }
  const attached = rt.exports.dune_web_attach_virtual_window(width, height);
  if (attached) rt.exports.dune_web_resize(width, height);
  return attached;
}

export default { loadRuntime, initRuntime, readAbi, createMemory, attachVirtualWindow };
